'use client';

/**
 * FileRegistry contract bindings — Ethereum Sepolia (11155111)
 *
 * ABI, address, and deployment block are auto-generated by:
 *   cd hardhat && npx ts-node scripts/export-abi.ts
 *
 * Do NOT hand-edit this file.  Run the script above after any redeployment.
 */
export {
  FILE_REGISTRY_ABI,
  FILE_REGISTRY_ADDRESS,
  SEPOLIA_CHAIN_ID,
  DEPLOYMENT_BLOCK,
} from './generated/FileRegistry';

/**
 * Runtime guard: reads address from env (useful for preview/staging environments).
 * Prefers the generated constant; falls back to env var if set.
 */
export function getFileRegistryAddress(): `0x${string}` | undefined {
  const addr = process.env.NEXT_PUBLIC_FILE_REGISTRY_ADDRESS;
  if (!addr || addr === '0x0000000000000000000000000000000000000000') return undefined;
  return addr as `0x${string}`;
}
